use super::util;

pub fn camelize(word: &str) -> String {
    let mut bytes = Vec::with_capacity(word.len());
    let mut uppercase_next = false;

    for &byte in word.as_bytes() {
        if byte == b'_' {
            uppercase_next = true;
            continue;
        }

        if uppercase_next {
            bytes.push(byte.to_ascii_uppercase());
            uppercase_next = false;
        } else {
            bytes.push(byte);
        }
    }

    String::from_utf8(bytes).expect("ASCII byte edits preserve UTF-8")
}

pub fn underscore(word: &str) -> String {
    let mut bytes = Vec::with_capacity(word.len() * 2);

    for (index, &byte) in word.as_bytes().iter().enumerate() {
        if byte.is_ascii_uppercase() {
            if index != 0 {
                bytes.push(b'_');
            }
            bytes.push(byte.to_ascii_lowercase());
        } else {
            bytes.push(byte);
        }
    }

    String::from_utf8(bytes).expect("ASCII byte edits preserve UTF-8")
}

pub fn humanize(word: &str) -> String {
    let spaced = util::replace_byte(word, b'_', b' ');
    util::capitalize_first_ascii_lower(&spaced)
}

pub fn dasherize(word: &str) -> String {
    util::replace_byte(word, b'_', b'-')
}

pub fn upcase(word: &str) -> String {
    util::map_ascii(word, u8::to_ascii_uppercase)
}

pub fn downcase(word: &str) -> String {
    util::map_ascii(word, u8::to_ascii_lowercase)
}

