pub fn capitalize_first_ascii_lower(input: &str) -> String {
    let mut bytes = input.as_bytes().to_vec();

    if let Some(first) = bytes.first_mut() {
        if first.is_ascii_lowercase() {
            *first = first.to_ascii_uppercase();
        }
    }

    String::from_utf8(bytes).expect("ASCII byte edits preserve UTF-8")
}

pub fn replace_byte(input: &str, from: u8, to: u8) -> String {
    let mut bytes = input.as_bytes().to_vec();

    for byte in &mut bytes {
        if *byte == from {
            *byte = to;
        }
    }

    String::from_utf8(bytes).expect("ASCII byte edits preserve UTF-8")
}

pub fn map_ascii(input: &str, mapper: fn(u8) -> u8) -> String {
    let bytes: Vec<u8> = input.as_bytes().iter().copied().map(mapper).collect();
    String::from_utf8(bytes).expect("ASCII byte edits preserve UTF-8")
}

